import shioMark from "@/assets/logos/shio.svg"
import shioMarkSmall from "@/assets/logos/shio-small.svg"

interface ShLogoProps {
    readonly size?: number;
    readonly className?: string;
}

/**
 * The Viglet Shio mark: an isometric cube with its front-top corner cut in the
 * angle of the Viglet V and "Sh" on its left face. The SVGs are generated by
 * make_marks.py in the alegauss/visibility repository (marca/logo/); copy them over
 * after regenerating, do not edit them by hand. Below 56 px the cube is drawn
 * without the symbol, which stops reading there.
 */
export function ShLogo({ size = 48, className }: ShLogoProps) {
    return (
        <img
            src={size < 56 ? shioMarkSmall : shioMark}
            alt="Viglet Shio"
            width={size}
            height={size}
            className={className}
            draggable={false}
        />
    )
}
